#!/usr/bin/env bash
# One-time project setup for EZ Workforce.
#
# The repository ships the Dart code, the Supabase migrations and the docs.
# The native platform folders (android/, ios/, web/) are generated by Flutter,
# so this script creates them and applies the two native settings the app
# needs. Run it once from the project root:
#
#   ./setup.sh
#
set -euo pipefail

cd "$(dirname "$0")"

if ! command -v flutter >/dev/null 2>&1; then
  echo "Flutter was not found on your PATH."
  echo "Install it from https://docs.flutter.dev/get-started/install and run this script again."
  exit 1
fi

echo "==> Generating platform folders (android, ios, web)"
flutter create . \
  --platforms=android,ios,web \
  --project-name ez_workforce \
  --org com.ezworkforce

# flutter create adds a counter-app widget test that does not apply here.
if [ -f test/widget_test.dart ] && grep -q "MyApp" test/widget_test.dart; then
  rm test/widget_test.dart
  echo "==> Removed the generated sample widget test"
fi

echo "==> Installing packages"
flutter pub get

MANIFEST="android/app/src/main/AndroidManifest.xml"
if [ -f "$MANIFEST" ] && ! grep -q "android.permission.INTERNET" "$MANIFEST"; then
  echo "==> Adding the INTERNET permission to the Android manifest"
  sed -i.bak '/<application/i\
    <uses-permission android:name="android.permission.INTERNET" />
' "$MANIFEST"
  rm -f "$MANIFEST.bak"
fi

PLIST="ios/Runner/Info.plist"
if [ -f "$PLIST" ] && ! grep -q "NSPhotoLibraryUsageDescription" "$PLIST"; then
  echo "==> Adding photo and camera usage descriptions to the iOS Info.plist"
  # Insert before the last closing dict, which ends the top-level dictionary.
  LAST_DICT=$(grep -n "</dict>" "$PLIST" | tail -1 | cut -d: -f1)
  sed -i.bak "${LAST_DICT}i\\
	<key>NSPhotoLibraryUsageDescription</key>\\
	<string>Choose a profile photo or a document to upload.</string>\\
	<key>NSCameraUsageDescription</key>\\
	<string>Take a profile photo.</string>
" "$PLIST"
  rm -f "$PLIST.bak"
fi

cat <<'MSG'

Setup finished.

Next:
  1. Create a Supabase project and apply the SQL in supabase/migrations
     (see docs/SETUP.md, steps 1 to 3).
  2. Run the app:

     flutter run -d chrome \
       --dart-define=SUPABASE_URL=https://YOUR-REF.supabase.co \
       --dart-define=SUPABASE_ANON_KEY=YOUR-ANON-KEY

  3. Check the code before the first run:

     flutter analyze
     flutter test
MSG
